SELECT cron.schedule('membership-freeze-due','35 18 * * *',$job$SELECT public.process_due_membership_freezes() WHERE EXISTS(SELECT 1 FROM public.membership_freeze_history WHERE status='approved' AND resumed_at IS NULL AND ((applied_at IS NULL AND start_date<=timezone('Asia/Kolkata',now())::date) OR (applied_at IS NOT NULL AND end_date<timezone('Asia/Kolkata',now())::date)));$job$);